'use strict';

/**
 * SQLite schema for the Monster Hunter Wilds builder.
 *
 * Game data tables are fully regenerated by `npm run seed`.
 * Community tables (builds, build_likes) are never dropped by the seed.
 */

const GAME_TABLES = [
  'meta', 'skills', 'items', 'monsters', 'item_sources',
  'weapons', 'weapon_materials', 'armor_sets', 'armor', 'armor_materials',
  'decorations', 'charms', 'charm_materials'
];

const GAME_SCHEMA = `
  CREATE TABLE meta (
    key   TEXT PRIMARY KEY,
    value TEXT
  );

  CREATE TABLE skills (
    id        INTEGER PRIMARY KEY,
    kind      TEXT NOT NULL,            -- weapon | armor | set | group
    icon      TEXT,
    max_level INTEGER NOT NULL,
    name_en   TEXT NOT NULL,
    name_fr   TEXT NOT NULL,
    desc_en   TEXT,
    desc_fr   TEXT,
    ranks_en  TEXT NOT NULL,            -- JSON [{level, name, description, pieces}]
    ranks_fr  TEXT NOT NULL
  );

  CREATE TABLE items (
    id          INTEGER PRIMARY KEY,
    rarity      INTEGER,
    value       INTEGER,
    carry_limit INTEGER,
    icon_kind   TEXT,
    icon_color  TEXT,
    name_en     TEXT NOT NULL,
    name_fr     TEXT NOT NULL,
    desc_en     TEXT,
    desc_fr     TEXT
  );

  CREATE TABLE monsters (
    id          INTEGER PRIMARY KEY,
    kind        TEXT,
    species     TEXT,
    hr_unlock   INTEGER NOT NULL,       -- estimated HR needed to hunt it in High Rank
    name_en     TEXT NOT NULL,
    name_fr     TEXT NOT NULL,
    desc_en     TEXT,
    desc_fr     TEXT,
    weaknesses  TEXT,                   -- JSON [{type, level, condition}]
    resistances TEXT,                   -- JSON [type]
    locations_en TEXT,                  -- JSON [name]
    locations_fr TEXT
  );

  CREATE TABLE item_sources (
    item_id    INTEGER NOT NULL REFERENCES items(id),
    monster_id INTEGER NOT NULL REFERENCES monsters(id),
    rank       TEXT NOT NULL,
    PRIMARY KEY (item_id, monster_id, rank)
  );

  CREATE TABLE weapons (
    id            INTEGER PRIMARY KEY,
    kind          TEXT NOT NULL,
    rarity        INTEGER NOT NULL,
    rank          TEXT NOT NULL,        -- low | high
    hr            INTEGER NOT NULL,     -- estimated minimum Hunter Rank
    name_en       TEXT NOT NULL,
    name_fr       TEXT NOT NULL,
    desc_en       TEXT,
    desc_fr       TEXT,
    series_en     TEXT,
    series_fr     TEXT,
    attack        INTEGER NOT NULL,     -- displayed attack
    attack_raw    INTEGER NOT NULL,
    affinity      INTEGER NOT NULL,
    defense_bonus INTEGER NOT NULL,
    element       TEXT,                 -- fire | water | ... | poison | paralysis ...
    element_value INTEGER,
    element_hidden INTEGER NOT NULL DEFAULT 0,
    elderseal     TEXT,
    slots         TEXT NOT NULL,        -- JSON [3,2,1]
    skills        TEXT NOT NULL,        -- JSON [[skillId, level]]
    sharpness     TEXT,                 -- JSON [red, orange, yellow, green, blue, white, purple]
    handicraft    TEXT,                 -- JSON
    extra         TEXT,                 -- JSON (phial, shell, ammo, coatings, kinsect, melody ...)
    previous_id   INTEGER,
    craftable     INTEGER NOT NULL,
    craft_zenny   INTEGER NOT NULL,
    upgrade_zenny INTEGER NOT NULL
  );
  CREATE INDEX weapons_kind ON weapons(kind);

  CREATE TABLE weapon_materials (
    weapon_id INTEGER NOT NULL REFERENCES weapons(id),
    item_id   INTEGER NOT NULL REFERENCES items(id),
    quantity  INTEGER NOT NULL,
    type      TEXT NOT NULL             -- craft | upgrade
  );
  CREATE INDEX weapon_materials_weapon ON weapon_materials(weapon_id);

  CREATE TABLE armor_sets (
    id             INTEGER PRIMARY KEY,
    rank           TEXT NOT NULL,
    rarity         INTEGER NOT NULL,
    hr             INTEGER NOT NULL,
    name_en        TEXT NOT NULL,
    name_fr        TEXT NOT NULL,
    set_skill_id   INTEGER REFERENCES skills(id),
    group_skill_id INTEGER REFERENCES skills(id)
  );

  CREATE TABLE armor (
    id           INTEGER PRIMARY KEY,
    set_id       INTEGER REFERENCES armor_sets(id),
    kind         TEXT NOT NULL,         -- head | chest | arms | waist | legs
    rank         TEXT NOT NULL,
    rarity       INTEGER NOT NULL,
    hr           INTEGER NOT NULL,
    name_en      TEXT NOT NULL,
    name_fr      TEXT NOT NULL,
    desc_en      TEXT,
    desc_fr      TEXT,
    defense_base INTEGER NOT NULL,
    defense_max  INTEGER NOT NULL,
    resistances  TEXT NOT NULL,         -- JSON [fire, water, thunder, ice, dragon]
    slots        TEXT NOT NULL,
    skills       TEXT NOT NULL,         -- JSON [[skillId, level]] (armor skills only)
    zenny        INTEGER NOT NULL
  );
  CREATE INDEX armor_kind ON armor(kind);

  CREATE TABLE armor_materials (
    armor_id INTEGER NOT NULL REFERENCES armor(id),
    item_id  INTEGER NOT NULL REFERENCES items(id),
    quantity INTEGER NOT NULL
  );
  CREATE INDEX armor_materials_armor ON armor_materials(armor_id);

  CREATE TABLE decorations (
    id      INTEGER PRIMARY KEY,
    kind    TEXT NOT NULL,              -- weapon | armor
    slot    INTEGER NOT NULL,
    rarity  INTEGER NOT NULL,
    name_en TEXT NOT NULL,
    name_fr TEXT NOT NULL,
    skills  TEXT NOT NULL               -- JSON [[skillId, level]]
  );

  CREATE TABLE charms (
    id         INTEGER PRIMARY KEY,     -- charm rank id
    charm_id   INTEGER NOT NULL,        -- charm family
    level      INTEGER NOT NULL,
    rarity     INTEGER NOT NULL,
    hr         INTEGER NOT NULL,
    name_en    TEXT NOT NULL,
    name_fr    TEXT NOT NULL,
    skills     TEXT NOT NULL,
    craftable  INTEGER NOT NULL,
    zenny      INTEGER NOT NULL
  );

  CREATE TABLE charm_materials (
    charm_id INTEGER NOT NULL REFERENCES charms(id),
    item_id  INTEGER NOT NULL REFERENCES items(id),
    quantity INTEGER NOT NULL
  );
  CREATE INDEX charm_materials_charm ON charm_materials(charm_id);
`;

const COMMUNITY_SCHEMA = `
  CREATE TABLE IF NOT EXISTS builds (
    id          TEXT PRIMARY KEY,
    type        TEXT NOT NULL DEFAULT 'build',  -- build | cosmetic
    token_hash  TEXT NOT NULL,
    name        TEXT NOT NULL,
    author      TEXT,
    description TEXT,
    weapon_kind TEXT,
    playstyle   TEXT,
    hr          INTEGER,
    rank        TEXT,
    lang        TEXT,
    data        TEXT NOT NULL,          -- JSON build (gear ids + decorations)
    likes       INTEGER NOT NULL DEFAULT 0,
    views       INTEGER NOT NULL DEFAULT 0,
    created_at  DATETIME DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME DEFAULT CURRENT_TIMESTAMP
  );
  CREATE INDEX IF NOT EXISTS builds_created ON builds(created_at);
  CREATE INDEX IF NOT EXISTS builds_likes ON builds(likes);

  CREATE TABLE IF NOT EXISTS build_likes (
    build_id TEXT NOT NULL REFERENCES builds(id) ON DELETE CASCADE,
    voter    TEXT NOT NULL,
    PRIMARY KEY (build_id, voter)
  );
`;

function createGameSchema(db) {
  db.pragma('foreign_keys = OFF');
  for (const table of GAME_TABLES) db.exec(`DROP TABLE IF EXISTS ${table}`);
  // Legacy tables from the first prototype.
  db.exec('DROP TABLE IF EXISTS hunters; DROP TABLE IF EXISTS favorites;');
  db.exec(GAME_SCHEMA);
}

function createCommunitySchema(db) {
  db.exec(COMMUNITY_SCHEMA);
  // Migration: builds created before cosmetic sets existed.
  const columns = db.prepare('PRAGMA table_info(builds)').all().map(c => c.name);
  if (!columns.includes('type')) db.exec("ALTER TABLE builds ADD COLUMN type TEXT NOT NULL DEFAULT 'build'");
  db.exec('CREATE INDEX IF NOT EXISTS builds_type ON builds(type)');
}

module.exports = { createGameSchema, createCommunitySchema, GAME_TABLES };
